
-- SQL schema for ICRISAT cleaned table
CREATE TABLE icrisat_district_cleaned (
    id SERIAL PRIMARY KEY,
    state TEXT,
    district TEXT,
    year INTEGER,
    rice_area_ha DOUBLE PRECISION,
    rice_prod_t DOUBLE PRECISION,
    rice_yield DOUBLE PRECISION,
    rice_area_ha_missing BOOLEAN,
    rice_prod_t_missing BOOLEAN,
    rice_yield_missing BOOLEAN
);

